//! Table metadata and the insert-value type.

use alloc::vec::Vec;

use besu_core::{TableDef, Value};

/// A table you can query.
///
/// Implemented by the zero-sized table handle generated by `#[derive(Table)]`. The handle
/// has one field per column, which is why `users.id` works and why copying it around is
/// free.
pub trait Table: Copy + 'static {
    /// The row type decoded from a `SELECT`.
    type Model: 'static;

    /// The struct used to insert a new row.
    type Insert: Insertable;

    /// The table's static metadata: name, columns, indexes and foreign keys.
    const DEF: &'static TableDef;

    /// The table's static metadata.
    fn def(&self) -> &'static TableDef {
        Self::DEF
    }

    /// The table's SQL name.
    fn name() -> &'static str {
        Self::DEF.name
    }
}

/// A new row to be inserted.
///
/// Implemented by the insert struct generated by `#[derive(Table)]`. Each column is a
/// [`Set`], so "not provided" is distinct from "provided as `NULL`" — the difference between
/// letting a database default apply or explicitly inserting `NULL`.
pub trait Insertable {
    /// Every column of the table, in the order [`Insertable::into_values`] returns them.
    const COLUMNS: &'static [&'static str];

    /// One entry per column: `None` means "not provided".
    fn into_values(self) -> Vec<Option<Value>>;
}

/// A column value in an `INSERT` or `UPDATE`.
///
/// The three states matter: [`Set::Unset`] lets the database apply its default,
/// [`Set::Null`] writes an explicit `NULL`, and [`Set::Value`] writes a value.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
pub enum Set<T> {
    /// The column was not provided.
    #[default]
    Unset,
    /// The column was explicitly set to `NULL`.
    Null,
    /// The column was set to a value.
    Value(T),
}

impl<T> Set<T> {
    /// Whether a value (including `NULL`) was provided.
    pub const fn is_set(&self) -> bool {
        !matches!(self, Self::Unset)
    }

    /// The underlying value, if any.
    pub const fn as_ref(&self) -> Option<&T> {
        match self {
            Self::Value(value) => Some(value),
            _ => None,
        }
    }

    /// Convert into a bound SQL value, or `None` if the column was not provided.
    pub fn to_value(&self) -> Option<Value>
    where
        T: Clone + Into<Value>,
    {
        match self {
            Self::Unset => None,
            Self::Null => Some(Value::Null),
            Self::Value(value) => Some(value.clone().into()),
        }
    }
}

impl<T> From<T> for Set<T> {
    fn from(value: T) -> Self {
        Self::Value(value)
    }
}

// Text and binary literals are common enough that requiring `.to_string()` everywhere would
// be noise. These do not overlap with the blanket impl because the `Set` type parameter
// differs.
impl From<&str> for Set<String> {
    fn from(value: &str) -> Self {
        Self::Value(value.into())
    }
}

impl From<&[u8]> for Set<Vec<u8>> {
    fn from(value: &[u8]) -> Self {
        Self::Value(value.into())
    }
}

impl<T> From<Option<T>> for Set<T> {
    fn from(value: Option<T>) -> Self {
        match value {
            Some(value) => Self::Value(value),
            None => Self::Null,
        }
    }
}

impl<T> From<Set<T>> for Option<Value>
where
    T: Into<Value>,
{
    fn from(value: Set<T>) -> Self {
        match value {
            Set::Unset => None,
            Set::Null => Some(Value::Null),
            Set::Value(value) => Some(value.into()),
        }
    }
}
